def dump_scan(path):
    d=open(path,'rb').read()
    # find SOS
    for i in range(len(d)):
        if d[i]==0xFF and d[i+1]==0xDA:
            ln=(d[i+2]<<8|d[i+3])
            start=i+2+ln
            # find EOI FFD9 at end
            print(path, "SOS at", i, "scan start", start, "scan len", len(d)-start-2, "file len", len(d))
            print("  scan hex", d[start:start+20].hex())
            return
for f in ["/tmp/sq16.jpg","/tmp/sq22.jpg","/tmp/w16h21.jpg","/tmp/w16h22.jpg","/tmp/s40x25.jpg","/tmp/r40x10.jpg"]:
    dump_scan(f)
