import sys
sys.path.insert(0,'/tmp')
from mkjpeg import write_jpeg_grayscale
from mkcolor2 import write_color
import subprocess
def run(args):
    import subprocess as sp
    r=sp.run(["./executable"]+args, capture_output=True)
    return r.stdout.decode(errors='ignore'), r.stderr.decode(errors='ignore')

# Test 1-comp grays
results={}
for v in range(256):
    write_jpeg_grayscale(16,16,[[v]*16 for _ in range(16)],[1]*64,"/tmp/t1.jpg")
    for gs in [False, True]:
        extra=["--grayscale"] if gs else []
        out,_=run(["--width=4","--colors"]+extra+["/tmp/t1.jpg"])
        # first char + ansi?
        line=out.splitlines()[0]
        # line contains ansi? e.g., '\x1b[37m \x1b[0m...' or '    ' or '\x1b[1mM...'
        # Determine code: check for \x1b[37m, \x1b[1m, or none
        if "\x1b[37m" in line:
            code="37"
        elif "\x1b[1m" in line:
            code="1"
        elif "\x1b[" in line:
            code="other:"+repr(line[:20])
        else:
            code="plain"
        results[(v,1,gs)]=code
    if v%50==0:
        print(f"1-comp {v} done")

for v in range(256):
    write_color(16,16,[[(v,v,v)]*16 for _ in range(16)],"/tmp/tc.jpg")
    for gs in [False, True]:
        extra=["--grayscale"] if gs else []
        out,_=run(["--width=4","--colors"]+extra+["/tmp/tc.jpg"])
        line=out.splitlines()[0]
        if "\x1b[37m" in line:
            code="37"
        elif "\x1b[1m" in line:
            code="1"
        elif "\x1b[" in line:
            code="other"
        else:
            code="plain"
        results[(v,3,gs)]=code
    if v%50==0:
        print(f"3-comp {v} done")

# Save
import pickle
open("/tmp/ansi_table.pkl","wb").write(pickle.dumps(results))
# Print summaries
